import re

SQL_BLOCK = re.compile(r"```(?:sql|sqlite)?\s*(.*?)```", re.S | re.I)
IDENT = r"[A-Za-z_][A-Za-z0-9_]*"
CREATE_RE = re.compile(
    r"CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?[\"'`\[]?(" + IDENT + r")", re.I
)
COL_RE = re.compile(r"^\s*[\"'`\[]?(" + IDENT + r")[\"'`\]]?\s+(.+?)\s*,?\s*$")
FK_RE = re.compile(
    r"FOREIGN\s+KEY\s*\(([^)]*)\)\s*REFERENCES\s+[\"'`\[]?(" + IDENT + r")[\"'`\]]?\s*\(([^)]*)\)",
    re.I,
)
LIT_RE = re.compile(r"'([^']*)'")
LIKE_RE = re.compile(
    r"([A-Za-z_][A-Za-z0-9_.]*)\s+(?:NOT\s+)?LIKE\s+'([^']*)'", re.I
)
EQ_RE = re.compile(r"([A-Za-z_][A-Za-z0-9_.]*)\s*=\s*'([^']*)'")
WHERE_SPLIT = re.compile(r"\bAND\b|\bOR\b", re.I)


# --------------------------------------------------------------------------- #
# small helpers
# --------------------------------------------------------------------------- #
def _cfg(env, key, default):
    try:
        return env.config.get(key, default)
    except Exception:
        return default


def _safe(fn, *a, **kw):
    try:
        return fn(*a, **kw)
    except Exception:
        return None


def extract_sql(text):
    text = text or ""
    blocks = [b.strip() for b in SQL_BLOCK.findall(text) if b.strip()]
    cand = blocks[-1] if blocks else text
    cand = cand.strip()
    m = re.search(r"(?is)\b(WITH|SELECT)\b", cand)
    if m:
        cand = cand[m.start():]
    cand = cand.strip().rstrip(";").strip()
    return cand


def _looks_like_sql(s):
    return bool(s) and bool(re.match(r"(?is)^(SELECT|WITH)\b", s))


def _split_top(s, sep=","):
    """Split on a separator that is not inside quotes/brackets."""
    out, depth, quote, cur = [], 0, None, []
    for ch in s:
        if quote:
            cur.append(ch)
            if ch == quote:
                quote = None
            continue
        if ch in "'\"`":
            quote = ch
            cur.append(ch)
            continue
        if ch in "([":
            depth += 1
        elif ch in ")]":
            depth -= 1
        if ch == sep and depth == 0:
            out.append("".join(cur))
            cur = []
        else:
            cur.append(ch)
    out.append("".join(cur))
    return [x.strip() for x in out if x.strip()]


def parse_schema(schema_text):
    """table -> [(column, decl)], plus list of (child, ccols, parent, pcols)."""
    tables, fks = {}, []
    text = schema_text or ""
    marks = list(CREATE_RE.finditer(text))
    for i, m in enumerate(marks):
        name = m.group(1)
        start = text.find("(", m.end())
        if start < 0:
            continue
        end = len(text) if i + 1 == len(marks) else marks[i + 1].start()
        body = text[start + 1:end]
        depth, cut = 0, len(body)
        for j, ch in enumerate(body):
            if ch == "(":
                depth += 1
            elif ch == ")":
                if depth == 0:
                    cut = j
                    break
                depth -= 1
        body = body[:cut]
        cols = []
        for part in _split_top(body):
            if re.match(r"(?i)^(PRIMARY|FOREIGN|UNIQUE|CHECK|CONSTRAINT)\b", part):
                continue
            cm = COL_RE.match(part)
            if cm:
                cols.append((cm.group(1), cm.group(2)))
        tables[name.lower()] = {"name": name, "cols": cols}
        for fm in FK_RE.finditer(body):
            cc = [c.strip().strip("\"'`[]") for c in fm.group(1).split(",")]
            pc = [c.strip().strip("\"'`[]") for c in fm.group(3).split(",")]
            fks.append((name, cc, fm.group(2), pc))
    return tables, fks


def _fmt_rows(res, limit=6):
    rows = res.get("rows") or []
    lines = []
    for r in rows[:limit]:
        lines.append(str(list(r))[:220])
    return "\n".join(lines)


# --------------------------------------------------------------------------- #
# diagnostics fed back to the model when a draft looks wrong
# --------------------------------------------------------------------------- #
def _literal_probes(sql, env, budget=3):
    """For each string literal used with = or LIKE, show what is really stored."""
    seen, notes = set(), []
    pairs = EQ_RE.findall(sql) + LIKE_RE.findall(sql)
    for ref, lit in pairs:
        if budget <= 0:
            break
        col = ref.split(".")[-1]
        if (col.lower(), lit) in seen or not lit.strip():
            continue
        seen.add((col.lower(), lit))
        core = re.sub(r"[%_]", "", lit).strip()
        if len(core) < 3:
            continue
        probe = (
            "SELECT DISTINCT {c} FROM {t} WHERE {c} LIKE '%{v}%' LIMIT 8".format(
                c=col, t="{t}", v=core.replace("'", "''")
            )
        )
        # find a table that actually owns this column
        target = None
        for t in _tables_in_sql(sql):
            r = _safe(env.execute, probe.format(t=t), max_rows=8)
            if r and r.get("ok"):
                target = (t, r)
                break
        budget -= 1
        if target is None:
            continue
        t, r = target
        vals = [str(x[0]) for x in (r.get("rows") or [])]
        if vals:
            notes.append(
                "Stored values in {}.{} containing {!r}: {}".format(
                    t, col, core, "; ".join(repr(v) for v in vals[:8])
                )
            )
        else:
            notes.append(
                "No value in {}.{} contains {!r} at all - the filter text/column is wrong.".format(
                    t, col, core
                )
            )
    return notes


def _tables_in_sql(sql):
    out = []
    for m in re.finditer(r"(?i)\b(?:FROM|JOIN)\s+[\"'`\[]?(" + IDENT + r")", sql):
        t = m.group(1)
        if t.lower() not in [x.lower() for x in out]:
            out.append(t)
    return out


def _fk_notes(sql, fks):
    used = {t.lower() for t in _tables_in_sql(sql)}
    notes = []
    for child, cc, parent, pc in fks:
        if child.lower() in used and parent.lower() in used:
            notes.append(
                "Declared foreign key: {}.{} -> {}.{}".format(
                    child, ",".join(cc), parent, ",".join(pc)
                )
            )
    return notes[:6]


def _where_relaxation(sql, env):
    """Drop each top-level WHERE predicate in turn to locate the killer filter."""
    m = re.search(r"(?is)\bWHERE\b", sql)
    if not m:
        return []
    head, tail = sql[:m.start()], sql[m.end():]
    stop = re.search(r"(?i)\b(GROUP\s+BY|ORDER\s+BY|LIMIT|HAVING)\b", tail)
    cond, rest = (tail[:stop.start()], tail[stop.start():]) if stop else (tail, "")
    parts = _split_top(cond, sep=None) if False else WHERE_SPLIT.split(cond)
    if len(parts) < 2:
        return []
    notes = []
    for i in range(len(parts)):
        kept = [p for j, p in enumerate(parts) if j != i]
        glue = " AND "
        new = head + "WHERE " + glue.join(kept) + " " + rest
        r = _safe(env.execute, new, max_rows=3)
        if r and r.get("ok") and (r.get("n_rows") or 0) > 0:
            notes.append(
                "Removing the predicate «{}» makes the query return rows -> that predicate is the likely bug.".format(
                    parts[i].strip()[:120]
                )
            )
        if len(notes) >= 2:
            break
    return notes


def build_feedback(task, env, sql, res):
    lines = []
    ok = bool(res and res.get("ok"))
    if not ok:
        lines.append("SQLite ERROR: {}".format((res or {}).get("error", "unknown")))
    elif (res.get("n_rows") or 0) == 0:
        lines.append(
            "The query executed successfully but returned ZERO rows. For this kind of question that "
            "almost always means a wrong join key, a wrong column, or a literal whose spelling/case/"
            "spacing does not match the stored data - not that the answer is genuinely empty."
        )
    schema = _safe(env.schema, task["db_id"]) or ""
    _, fks = parse_schema(schema)
    lines += _fk_notes(sql, fks)
    lines += _literal_probes(sql, env)
    if ok and (res.get("n_rows") or 0) == 0:
        lines += _where_relaxation(sql, env)
    return "\n".join("- " + x for x in lines if x)


REPAIR_RULES = """Repair checklist (apply only what the evidence supports):
1. Join keys: use the declared foreign keys / matching id columns. Two tables may share a column NAME
   that is not the join key (e.g. a text code vs a numeric id); inspect the real values before joining.
2. String filters: match the stored spelling, case and spacing exactly. Use TRIM()/LOWER() or a
   correctly anchored LIKE pattern when the data has padding or different casing; do not invent values.
3. Column choice: pick the column whose sample values actually look like what the question asks for
   (a short label column vs a long description column, a name vs an id).
4. Set logic: "who has no X" must consider every column that can reference the entity (both sides of a
   relation table); prefer NOT EXISTS / EXCEPT over NOT IN when NULLs are possible.
5. Projection: if the question says "which/what <entity>" without naming attributes, return all columns
   of that entity's table (t.*), keeping the join/filter structure; only narrow the SELECT list when the
   question explicitly names the attributes.
6. Keep the answer semantically identical otherwise: same filters, same aggregation, same ORDER BY/LIMIT.
Return ONLY the corrected query in one ```sql block."""


# --------------------------------------------------------------------------- #
# main entry point
# --------------------------------------------------------------------------- #
def solve(task, env):
    db_id = task["db_id"]
    schema = _safe(env.schema, db_id) or ""
    desc = ""
    if _cfg(env, "use_descriptions", True):
        desc = (_safe(env.descriptions, db_id) or "").strip()
        if len(desc) > 4000:
            desc = desc[:4000]

    user = "Database: {}\n\nSchema:\n{}\n".format(db_id, schema)
    if desc:
        user += "\nColumn descriptions:\n{}\n".format(desc)
    user += "\nQuestion: {}".format(task["question"])
    if task.get("hint"):
        user += "\nHint: {}".format(task["hint"])
    user += (
        "\n\nWrite the single SQLite query that answers the question. "
        "Think briefly, then give the final query in one ```sql block."
    )

    messages = [
        {"role": "system", "content": env.prompt("system_prompt.md")},
        {"role": "user", "content": user},
    ]
    reply = env.chat(messages, max_tokens=_cfg(env, "max_tokens", 800))
    sql = extract_sql(reply)

    if not _cfg(env, "verify", True) or not _looks_like_sql(sql):
        return {"sql": sql}

    res = _safe(env.execute, sql, max_rows=20)
    if res is None:
        return {"sql": sql}

    ok = bool(res.get("ok"))
    nrows = res.get("n_rows") or 0
    needs_repair = (not ok) or (nrows == 0)
    if not needs_repair or _cfg(env, "max_calls", 2) < 2:
        return {"sql": sql}

    feedback = build_feedback(task, env, sql, res)
    preview = ""
    if ok and nrows:
        preview = "Columns: {}\nRows:\n{}".format(res.get("columns"), _fmt_rows(res))
    repair_user = (
        "Your draft query was:\n```sql\n{}\n```\n\nExecution feedback:\n{}\n{}\n\n{}\n\n"
        "Original question: {}{}".format(
            sql,
            feedback or "(no extra diagnostics available)",
            preview,
            REPAIR_RULES,
            task["question"],
            ("\nHint: " + task["hint"]) if task.get("hint") else "",
        )
    )
    messages2 = messages + [
        {"role": "assistant", "content": reply},
        {"role": "user", "content": repair_user},
    ]
    reply2 = _safe(env.chat, messages2, max_tokens=_cfg(env, "repair_max_tokens", 800))
    sql2 = extract_sql(reply2)
    if not _looks_like_sql(sql2):
        return {"sql": sql}

    res2 = _safe(env.execute, sql2, max_rows=20)
    if res2 is None:
        return {"sql": sql}
    if not res2.get("ok"):
        return {"sql": sql}          # keep the runnable draft over a broken repair
    if nrows == 0 and (res2.get("n_rows") or 0) == 0:
        return {"sql": sql2}         # both empty: trust the informed second attempt
    return {"sql": sql2}

